import{openAuditPage,pause}from'/workspace/trading101/docs/adsense-2026-10-22/browser-session.mjs';import{mkdirSync,writeFileSync}from'node:fs';import assert from'node:assert/strict';
const[sha,origin,stage]=process.argv.slice(2),root='/workspace/trading101/docs/adsense-2026-10-22/evidence/',folder=root+'editorial-contrast-'+stage+'-20261030';mkdirSync(folder,{recursive:true});const p=await openAuditPage('about:blank',Number(process.env.AUDIT_CDP_PORT||9258)),rows=[],errors=[],blocked=[];p.onEvent(m=>{if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.method==='Fetch.requestPaused'){const{requestId,request}=m.params,u=new URL(request.url),safe=['GET','HEAD','OPTIONS'].includes(request.method)||(request.method==='POST'&&u.pathname==='/rest/v1/rpc/get_published_course_catalog');if(!safe)blocked.push({method:request.method,path:u.pathname});p.send(safe?'Fetch.continueRequest':'Fetch.failRequest',safe?{requestId}:{requestId,errorReason:'Aborted'}).catch(()=>{});}});await p.send('Runtime.enable');await p.send('Fetch.enable',{patterns:[{urlPattern:'https://*.supabase.co/*',requestStage:'Request'}]});
const rgb=s=>{const a=s.match(/[\d.]+/g).map(Number);return[a[0],a[1],a[2],a[3]??1]},over=(f,b)=>f.slice(0,3).map((v,i)=>v*f[3]+b[i]*(1-f[3])),lum=c=>c.map(v=>v/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((a,v,i)=>a+v*[.2126,.7152,.0722][i],0),ratio=(a,b)=>(Math.max(lum(a),lum(b))+.05)/(Math.min(lum(a),lum(b))+.05);
